/**
 * PuzzleRenderer - Responsible for rendering the generated puzzle. Uses paper.js
 */

import m from 'mithril';
import type { PuzzleRendererAttrs, PuzzleRendererState } from './constants';
import type MithrilViewEvent from '../../utils/MithrilViewEvent';
import { DEFAULT_ZOOM, PRESET_ZOOM_LEVELS, PRESET_ZOOM_LABELS } from './constants';
import {
  initializePaper,
  syncPaperViewSize,
  renderPuzzle,
  createPaperLayers,
  cleanupPaper,
  updateBackgroundImage,
  renderCustomPieces,
  renderCustomPieceHandles,
  clearCustomPieceHandles,
} from './rendering';
import { drawRulers } from './ruler';
import {
  handleMouseMove,
  handleDragStart,
  handleDragMove,
  handleDragEnd,
  setupPanZoomHandling,
  cleanupPanZoomHandling,
} from './interaction';

// Include  CSS
import './PuzzleRenderer.css';

// Web Awesome components
import '@awesome.me/webawesome/dist/components/button/button.js';
import '@awesome.me/webawesome/dist/components/dropdown/dropdown.js';
import '@awesome.me/webawesome/dist/components/dropdown-item/dropdown-item.js';
import type WaDropdownItem from '@awesome.me/webawesome/dist/components/dropdown-item/dropdown-item.js';
import '@awesome.me/webawesome/dist/components/icon/icon.js';
import '@awesome.me/webawesome/dist/components/tooltip/tooltip.js';

/**
 * PuzzleRenderer - component that renders a puzzle using paper.js
 */
export const PuzzleRenderer: m.ClosureComponent<PuzzleRendererAttrs> = () => {
  // Component state
  const state: PuzzleRendererState = {
    canvas: null,
    rulerH: null,
    rulerV: null,
    rulerObserver: null,
    isDragging: false,
    draggedVertexId: -1,
    draggedSeedPointId: -1,
    lastRegenerationTime: 0,
    pendingRegeneration: null,
    documentMouseMove: null,
    documentMouseUp: null,

    // Paper.js items
    paperCtx: null,
    backgroundRaster: null,

    // Paper.js layer architecture
    puzzleLayer: null,
    customPiecesLayer: null,
    customHandlesLayer: null,
    seedPointsLayer: null,
    verticesLayer: null,
    problemsLayer: null,

    // Groups within layers
    paperPath: null,
    seedPointItems: null,
    problemItems: null,
    vertexItems: null,

    // Hover and selection state
    hoveredVertexId: -1,
    selectedPieceId: -1,

    // Custom piece interaction state
    draggedCustomPieceId: null,
    draggedHandleType: null,
    draggedCorner: null,
    customPieceDragStart: null,
    customPieceInitialTransform: null,
    customPieceInitialAngle: null,

    // Pan and zoom state
    zoom: DEFAULT_ZOOM,
    isSpacebarPressed: false,
  };

  // Most recent attrs, so view-transform changes (pan, wheel zoom) can redraw the
  // rulers without going through a Mithril redraw.
  let latestAttrs: PuzzleRendererAttrs | null = null;

  /** Redraw the rulers from the current Paper.js view transform */
  const refreshRulers = () => {
    if (latestAttrs) drawRulers(state, latestAttrs);
  };

  /**
   * Set zoom level programmatically (from dropdown selection)
   */
  const setZoom = (newZoom: number, attrs?: PuzzleRendererAttrs) => {
    if (newZoom === state.zoom || !state.paperCtx) return;

    const paperScope = state.paperCtx.scope;
    const zoomFactor = newZoom / state.zoom;
    paperScope.view.scale(zoomFactor, paperScope.view.center);
    state.zoom = newZoom;
    refreshRulers();

    // Notify parent of zoom change if callback provided
    if (attrs?.onZoomChanged) {
      attrs.onZoomChanged(newZoom);
    }

    m.redraw();
  };

  /**
   * Reset zoom to 100% and center the view
   */
  const recenter = () => {
    if (!state.paperCtx) return;

    const paperScope = state.paperCtx.scope;

    // Reset zoom to 100%
    const zoomFactor = DEFAULT_ZOOM / state.zoom;
    paperScope.view.scale(zoomFactor, paperScope.view.center);
    state.zoom = DEFAULT_ZOOM;

    // Pan to the middle of the view
    paperScope.view.center = new paperScope.Point(
      paperScope.view.viewSize.width / 2,
      paperScope.view.viewSize.height / 2
    );
    refreshRulers();
    m.redraw();
  };

  /**
   * Get the current zoom as a percentage string
   */
  const getZoomPercentage = (): string => {
    return `${Math.round(state.zoom * 100)}%`;
  };

  // Track previous imageUrl to detect changes
  let previousImageUrl: string | undefined = undefined;

  return {
    // Component lifecycle: called after DOM element is created and attached
    oncreate: ({ dom, attrs }) => {
      state.canvas = dom.querySelector<HTMLCanvasElement>("canvas.puzzle-renderer");
      if (!state.canvas) {
        console.error('PuzzleRenderer: couldn\'t get canvas element');
        return;
      }
      latestAttrs = attrs;
      state.rulerH = dom.querySelector<HTMLCanvasElement>("canvas.puzzle-ruler-h");
      state.rulerV = dom.querySelector<HTMLCanvasElement>("canvas.puzzle-ruler-v");

      // The puzzle canvas is sized by CSS, so its on-screen size can change without
      // any attribute change. Redraw the rulers whenever it does.
      state.rulerObserver = new ResizeObserver(() => refreshRulers());
      state.rulerObserver.observe(state.canvas);

      // Initialize Paper.js
      initializePaper(state.canvas, attrs.width, attrs.height, state);

      // Create Paper.js layer architecture
      createPaperLayers(state);

      // Set up pan and zoom event handlers
      setupPanZoomHandling(state, attrs.onZoomChanged, refreshRulers);

      // Load background image if present
      updateBackgroundImage(state, attrs.imageUrl, attrs.width, attrs.height);
      previousImageUrl = attrs.imageUrl;

      // Initial render
      if (attrs.puzzle && !attrs.isDirty) {
        renderPuzzle(state, attrs.puzzle, attrs.color, attrs.pointColor);
      }

      // Render custom pieces if present
      if (attrs.customPieces && attrs.customPieces.length > 0) {
        renderCustomPieces(state, attrs.customPieces, attrs.color, attrs.selectedCustomPieceId);

        // Render transform handles for selected custom piece
        if (attrs.selectedCustomPieceId) {
          const selectedPiece = attrs.customPieces.find((p) => p.id === attrs.selectedCustomPieceId && p.visible !== false);
          if (selectedPiece) {
            renderCustomPieceHandles(state, selectedPiece);
          }
        } else {
          clearCustomPieceHandles(state);
        }
      }

      refreshRulers();
    },

    // Component lifecycle: called when attributes change
    onupdate: ({ attrs }) => {
      latestAttrs = attrs;
      if (!state.canvas) {
        console.error('PuzzleRenderer: couldn\'t get canvas element');
        return;
      }

      // Aspect-ratio / dimension changes must update Paper.js before drawing.
      // Mithril does not own canvas.width/height (see view()); Paper.js does.
      const resized = syncPaperViewSize(state, attrs.width, attrs.height);

      // Update background image if it changed, or rescale it after a canvas resize
      if (attrs.imageUrl !== previousImageUrl || (resized && attrs.imageUrl)) {
        updateBackgroundImage(state, attrs.imageUrl, attrs.width, attrs.height);
        previousImageUrl = attrs.imageUrl;
      }

      // Re-render if puzzle is not being regenerated. After a resize, also
      // refresh the existing scene so the new backing store is fully painted
      // while a rebuild is still in flight.
      if (attrs.puzzle && !attrs.isDirty) {
        renderPuzzle(state, attrs.puzzle, attrs.color, attrs.pointColor);
      } else if (resized && state.paperCtx) {
        state.paperCtx.scope.view.update();
      }

      // Render custom pieces (always update them, even if puzzle is dirty)
      if (attrs.customPieces && attrs.customPieces.length > 0) {
        renderCustomPieces(state, attrs.customPieces, attrs.color, attrs.selectedCustomPieceId);

        // Render transform handles for selected custom piece
        if (attrs.selectedCustomPieceId) {
          const selectedPiece = attrs.customPieces.find((p) => p.id === attrs.selectedCustomPieceId && p.visible !== false);
          if (selectedPiece) {
            renderCustomPieceHandles(state, selectedPiece);
          }
        } else {
          clearCustomPieceHandles(state);
        }
      } else if (state.customPiecesLayer) {
        // Clear custom pieces layer if no custom pieces
        state.customPiecesLayer.removeChildren();
        clearCustomPieceHandles(state);
      }

      refreshRulers();
    },

    // Component lifecycle: cleanup when component is removed
    onremove: () => {
      // Clean up document-level listeners if component is destroyed during drag
      if (state.documentMouseMove) {
        document.removeEventListener('mousemove', state.documentMouseMove);
        state.documentMouseMove = null;
      }
      if (state.documentMouseUp) {
        document.removeEventListener('mouseup', state.documentMouseUp);
        state.documentMouseUp = null;
      }

      // Stop watching the canvas for layout changes
      state.rulerObserver?.disconnect();
      state.rulerObserver = null;

      // Clean up pan and zoom event handlers
      cleanupPanZoomHandling(state.canvas);

      // Clean up Paper.js resources
      cleanupPaper(state);
    },

    // Component lifecycle: render our output
    view: ({ attrs }) => {
      // Get current zoom as percentage string
      const currentZoomStr = getZoomPercentage();
      const allowVerticalScrolling = attrs.allowVerticalScrolling === true;

      const showRuler = attrs.showRuler !== false;

      return m('.puzzle-renderer-wrapper', {
        class: allowVerticalScrolling ? undefined : 'fit-viewport',
      }, [
        m('.puzzle-canvas-grid', {
          key: 'puzzle-canvas-grid',
          class: showRuler ? 'with-ruler' : undefined,
        }, [
        // Rulers along the top and left edges (plain 2d canvases, not Paper.js)
          m('.puzzle-ruler-corner', { key: 'puzzle-ruler-corner' }),
          m('canvas.puzzle-ruler-h', { key: 'puzzle-ruler-h' }),
          m('canvas.puzzle-ruler-v', { key: 'puzzle-ruler-v' }),

          // Canvas for rendering the puzzle with Paper.js (background image is now inside Paper.js)
          m('canvas.puzzle-renderer', {
            key: 'puzzle-renderer-canvas', // Stable key to prevent Mithril from replacing the canvas
            // Do not set width/height attributes here. Assigning them resets the
            // 2d context and fights Paper.js hidpi backing-store sizing, which
            // leaves stale/partial frames after aspect-ratio changes.
            style: {
              touchAction: 'manipulation',
              aspectRatio: `${attrs.width} / ${attrs.height}`,
            },

            // Mouse events
            onmousedown: (e: MouseEvent & MithrilViewEvent) => handleDragStart(e, attrs, state),
            onmousemove: (e: MouseEvent & MithrilViewEvent) => {
              handleMouseMove(e, attrs, state);
              handleDragMove(e, attrs, state);
            },
            onmouseup: (e: MouseEvent & MithrilViewEvent) => handleDragEnd(e, attrs, state),

            // Touch events
            ontouchstart: (e: TouchEvent & MithrilViewEvent) => handleDragStart(e, attrs, state),
            ontouchmove: (e: TouchEvent & MithrilViewEvent) => handleDragMove(e, attrs, state),
            ontouchend: (e: TouchEvent & MithrilViewEvent) => handleDragEnd(e, attrs, state),
            ontouchcancel: (e: TouchEvent & MithrilViewEvent) => handleDragEnd(e, attrs, state),
          }),
        ]),

        // Controls row
        m('.puzzle-renderer-controls', {
          key: 'puzzle-renderer-controls', // Add key to all siblings
        }, [
          // Zoom control
          m('wa-dropdown.zoom-control', {
            'onwa-select': (e: CustomEvent<{ item: WaDropdownItem }> & MithrilViewEvent) => {
              e.redraw = false;
              const selectedValue = e.detail.item.value;

              if (selectedValue && typeof selectedValue === 'string') {
                const newZoom = parseFloat(selectedValue);
                if (!isNaN(newZoom)) {
                  setZoom(newZoom, attrs);
                }
              }
            },
          }, [
            m('wa-button', {
              slot: 'trigger',
              'with-caret': true,
              size: 's',
              value: state.zoom,
            }, currentZoomStr),
            ...PRESET_ZOOM_LEVELS.map((level, index) =>
              m('wa-dropdown-item', {
                type: 'checkbox',
                checked: state.zoom == level ? true : undefined,
                value: level.toString(),
              }, PRESET_ZOOM_LABELS[index])
            ),
          ]),

          // Recenter button
          m('wa-tooltip', { for: "recenter-button" }, "Recenter view"),
          m('wa-button#recenter-button', {
            appearance: 'plain',
            size: 'l',
            onclick: () => {
              recenter();
            },
          }, m('wa-icon', {
            library: 'material',
            name: 'recenter',
            label: 'Recenter view',
          })),
        ]),
      ]);
    },
  };
};

export default PuzzleRenderer;
